import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/* IncrementalAlterConfigs Request (Version: 0) => [resources] validate_only; configs => name config_operation value */
export function createRequest(resources, validateOnly) { return Writer.create().appendArray(resources, (w, r) => w.appendInt8(r.resourceType).appendString(r.resourceName, false).appendArray(r.configs, (w, c) => w.appendString(c.name, false).appendInt8(c.configOperation).appendString(c.value, false), false, false), false, false).appendBoolean(validateOnly); }
/* IncrementalAlterConfigs Response (Version: 0) => throttle_time_ms [responses]; responses => error_code error_message resource_type resource_name */
export function parseResponse(_, apiKey, apiVersion, reader) { const errors = []; const response = { throttleTimeMs: reader.readInt32(), responses: reader.readArray((r, i) => { const errorCode = r.readInt16(); const errorMessage = r.readNullableString(false); if (errorCode)
        errors.push([`/responses/${i}`, [errorCode, errorMessage]]); return { errorCode, errorMessage, resourceType: r.readInt8(), resourceName: r.readString(false) }; }, false, false) }; if (errors.length)
    throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response); return response; }
export const api = createAPI(44, 0, createRequest, parseResponse, false, false);
